import json
import os
import subprocess
import sys
from datetime import datetime

def main():
    current_token = sys.stdin.readline().strip()
    accounts = json.load(open('accounts.json'))
    current_owner = None

    for owner, verifier in accounts.items():
        if verifier['token'] == current_token:
            current_owner = owner
            break

    if current_owner is None:
        print("Unknown token", file=sys.stderr)
        sys.exit(1)

    tasks = json.load(open('tasks.json'))

    state = {}
    if os.path.exists('state.json'):
        state = json.load(open('state.json'))

    current_time = datetime.now().timestamp()

    for task in tasks:
        if task['owner'] == current_owner:
            if 'state.json' not in os.listdir('.'):
                state[current_owner] = []

            timestamps = state[current_owner]
            recent = [t for t in timestamps if t >= current_time - 60]
            if len(recent) >= 5:
                print(f"Rate limit exceeded for {current_owner}")
                continue

            command = ' '.join(task['command'])
            print(f"Ran {command} for {current_owner}")
            subprocess.run(task['command'], check=True)
            state[current_owner].append(current_time)

    for owner in state:
        state[owner] = [t for t in state[owner] if t >= current_time - 60]

    with open('state.json', 'w') as f:
        json.dump(state, f)

if __name__ == "__main__":
    main()
